// Initialize variables
let money = getMoney();

// Function to calculate profit from hacking servers
function calcProfit(server) {
    let hackChance = server.hackDifficulty / server.requiredHackingSkill;
    if (hackChance >= 1) return -Infinity; // Unhackable
    let weakenTime = Math.ceil((server.baseDifficulty - server.hackDifficulty) * 20);
    let growthRate = Math.pow(2, server.moneyGrowPercent / 4000);
    let profitPerCycle = money * (growthRate - 1);
    return profitPerCycle / weakenTime;
}

// Identify the most profitable server to hack
let servers = getServers();
let maxProfitServer = null;
let maxProfit = -Infinity;
for (let server of servers) {
    if (canHack(server)) {
        let profit = calcProfit(server);
        if (profit > maxProfit) {
            maxProfit = profit;
            maxProfitServer = server;
        }
    }
}

