export async function main(ns) {
    while (true) {
        let coin = ns.scan(0).filter(x => ns.getServer(x).hasAdminRights && x !== "home").map(x => ns.getHackStats()[x].hacking_level > 1 ? ns.getServer(x).coins : 0);
        if (!coin.some(c => c > 0)) break;
        let target = coin.reduce((a, b) => a.coins > b.coins ? a : b);
        await ns.singularity.goToLocation(target.location);
        ns.sleep(1000);
    }
}

const nodes = ['hong-faction', 'w0rldd313'];
let queue = [...nodes];
let visited = new Set(queue);

while (queue.length) {
    const node = queue.shift();
    const loot = ns.gather(node);
    if (loot.coins > 0 || loot.powerups > 0) {
        ns.tprint(`Collected ${loot.coins} coins and ${loot.powerups} power-ups at ${node}`);
    }
    for (const neighbor of ns.adjacencyList(node)) {
        if (!visited.has(neighbor)) {
            visited.add(neighbor);
            queue.push(neighbor);
        }
    }
